#!/bin/sh
# Builds kaggle/ctc_text/kernel.py: (1) literal CTC transcripts with wav2vec2-large-960h-lv60-self, one shard per GPU;
# (2) DeBERTa-v3-large fine-tuned on those transcripts (src/ft_text.py), speaker-grouped folds, folds split over 2 GPUs.
cd "$(dirname "$0")/.."
B_CTC=$(base64 < src/transcribe_ctc.py | tr -d '\n')
B_FT=$(base64 < src/ft_text.py | tr -d '\n')
FOLDS=$(base64 < cache/folds_grouped_r0.csv | tr -d '\n')
cat > kaggle/ctc_text/kernel.py <<PY
# Kaggle kernel: literal CTC transcripts + DeBERTa fine-tuning on them. Generated by kaggle/build_ctc_text.sh.
import base64, glob, json, os, subprocess, sys, threading, time
import torch
from huggingface_hub import model_info, snapshot_download
OUT = "/kaggle/working"
open("/tmp/transcribe_ctc.py", "w").write(base64.b64decode("$B_CTC").decode())
open("/tmp/ft_text.py", "w").write(base64.b64decode("$B_FT").decode())
open("/tmp/folds.csv", "w").write(base64.b64decode("$FOLDS").decode())
DATA = os.path.dirname(glob.glob("/kaggle/input/**/train.csv", recursive=True)[0])
for m in ("facebook/wav2vec2-large-960h-lv60-self", "microsoft/deberta-v3-large"):
    snapshot_download(m)
    print("licence check:", m, (model_info(m).card_data or {}).get("license"), flush=True)
n = max(1, torch.cuda.device_count())
print("GPUs:", n, [torch.cuda.get_device_name(i) for i in range(n)], flush=True)
t0 = time.time()
ps = [subprocess.Popen([sys.executable, "/tmp/transcribe_ctc.py", "--data", DATA, "--out", OUT, "--shard", str(g), "--nshards", str(n)],
                       env={**os.environ, "CUDA_VISIBLE_DEVICES": str(g)}) for g in range(n)]
codes = [p.wait() for p in ps]
print("transcribe exit codes:", codes, "| %.0f min" % ((time.time() - t0) / 60), flush=True)
assert all(c == 0 for c in codes)
recs = [json.loads(l) for g in range(n) for l in open(f"{OUT}/ctc_transcripts.s{g}.jsonl")]
json.dump(recs, open(f"{OUT}/ctc_transcripts.json", "w"))
[os.remove(f"{OUT}/ctc_transcripts.s{g}.jsonl") for g in range(n)]
print("ctc transcripts:", len(recs), "| mean words", round(sum(len(r["text"].split()) for r in recs) / len(recs), 1), flush=True)
queues = [[k for k in range(5) if k % n == g] for g in range(n)]
fcodes = {}

def run_queue(g):
    for k in queues[g]:
        r = subprocess.run([sys.executable, "/tmp/ft_text.py", "--texts", f"{OUT}/ctc_transcripts.json", "--data", DATA,
                            "--folds", "/tmp/folds.csv", "--out", f"{OUT}/ft_ctc", "--fold", str(k), "--seeds", "3", "--epochs", "4"],
                           env={**os.environ, "CUDA_VISIBLE_DEVICES": str(g)})
        fcodes[k] = r.returncode

th = [threading.Thread(target=run_queue, args=(g,)) for g in range(n)]
[t.start() for t in th]; [t.join() for t in th]
print("fine-tune exit codes:", fcodes, "| total %.0f min" % ((time.time() - t0) / 60), flush=True)
PY
echo "built kaggle/ctc_text/kernel.py"
